//! The screen fonts (src/ui_view.rs): the C++ firmware's pre-rendered faces,
//! src/ui_font_data.h (generated by tools/pack_display_fonts.py), turned into
//! Rust tables. Glyph coverage goes in as bytes.

use std::path::Path;
use std::{env, fs};

fn numbers(text: &str) -> Vec<i64> {
    text.split(|c: char| !(c.is_ascii_hexdigit() || c == 'x' || c == '-'))
        .filter(|t| !t.is_empty())
        .map(|t| match t.strip_prefix("0x") {
            Some(hex) => i64::from_str_radix(hex, 16).unwrap(),
            None => t.parse().unwrap(),
        })
        .collect()
}

fn between<'a>(text: &'a str, start: &str, end: &str) -> &'a str {
    let i = text.find(start).unwrap_or_else(|| panic!("ui_font_data.h: no {start}")) + start.len();
    let j = text[i..].find(end).unwrap() + i;
    &text[i..j]
}

fn main() {
    let path = Path::new(&env::var("CARGO_MANIFEST_DIR").unwrap()).join("../../src/ui_font_data.h");
    println!("cargo::rerun-if-changed={}", path.display());
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let out = Path::new(&env::var("OUT_DIR").unwrap()).to_path_buf();

    let glyphs = numbers(between(&text, "constexpr Glyph kGlyphs[] = {", "};"));
    assert_eq!(glyphs.len() % 5, 0);
    let coverage: Vec<u8> =
        numbers(between(&text, "constexpr uint8_t kCoverage[] = {", "};")).into_iter().map(|b| b as u8).collect();
    fs::write(out.join("ui_coverage.bin"), &coverage).unwrap();

    let faces_line = between(&text, "#define BDL_FONT_FACES", "\n");
    let mut faces = Vec::new();
    for face in faces_line.split('}').filter(|f| f.contains('{')) {
        let inner = face.split('{').nth(1).unwrap();
        let parts: Vec<&str> = inner.split(',').map(str::trim).collect();
        faces.push(format!(
            "Face {{ first: {}, height: {}, baseline: {}, numerals: {} }}",
            parts[0], parts[1], parts[2], parts[3]
        ));
    }
    let text_faces: usize = between(&text, "kTextFaces = ", ",").trim().parse().unwrap();
    let numeral_faces: usize = between(&text, "kNumeralFaces = ", ";").trim().parse().unwrap();
    let numerals = between(&text, "constexpr char kNumeralCharacters[] = \"", "\"");

    let mut rs = String::new();
    rs.push_str("// Generated by build.rs from src/ui_font_data.h.\n");
    rs.push_str(&format!("pub static GLYPHS: [Glyph; {}] = [\n", glyphs.len() / 5));
    for g in glyphs.chunks(5) {
        rs.push_str(&format!(
            "    Glyph {{ offset: {}, length: {}, width: {}, advance: {}, left: {} }},\n",
            g[0], g[1], g[2], g[3], g[4]
        ));
    }
    rs.push_str("];\n");
    rs.push_str(&format!("pub static FACES: [Face; {}] = [\n    {},\n];\n", faces.len(), faces.join(",\n    ")));
    rs.push_str(&format!("pub const TEXT_FACES: usize = {};\n", text_faces));
    rs.push_str(&format!("pub const NUMERAL_FACES: usize = {};\n", numeral_faces));
    rs.push_str(&format!("pub const NUMERAL_CHARACTERS: &str = {numerals:?};\n"));
    rs.push_str("pub static COVERAGE: &[u8] = include_bytes!(concat!(env!(\"OUT_DIR\"), \"/ui_coverage.bin\"));\n");
    fs::write(out.join("ui_font_data.rs"), rs).unwrap();
}
